```javascript
const crypto = require('crypto');

function encrypt_data(key, data) {
    // Extract a 32-byte (256-bit) key from the provided key bytes
    const keyUsed = key.slice(0, 32);

    // Generate a random 16-byte initialization vector (IV)
    const iv = crypto.randomBytes(16);

    try {
        // Create an AES-256-CBC cipher object with PKCS7 padding for better security
        const cipher = crypto.createCipheriv('aes-256-cbc', keyUsed, iv);

        // Encrypt the data in chunks to handle large payloads efficiently
        let encryptedData = [];
        if (data.length > 0) {
            encryptedData.push(cipher.update(data));
            encryptedData.push(cipher.final());
        }
        const encryptedBuffer = Buffer.concat(encryptedData);

        // Create a HMAC object for authentication using SHA-256
        const hmac = crypto.createHmac('sha256', keyUsed);
        hmac.update(iv).update(encryptedBuffer);
        const authTag = hmac.digest();

        // Return combined result including authentication tag for integrity verification
        return {
            encryptedData: encryptedBuffer,
            iv: iv,
            keyUsed: keyUsed,
            authTag: authTag
        };
    } catch (error) {
        // Handle any encryption errors gracefully
        throw new Error(`Encryption failed: ${error.message}`);
    }
}
```

